// Rule L7: `opt` without a value is an optional input previewing zero; 2.0 spells the zero.
/// @name DreamShaderTests/Migrate/MF_MgOpt
export void MF_MgOpt(float3 InColor, float Strength = 0.0, float4 Extra = float4(0.0, 0.0, 0.0, 1.0), out float3 OutColor)
{
    OutColor = InColor * Strength + Extra.rgb;
}
